class Solution {
    public int[] twoSum(int[] nums, int target) {
        var result = new int[2];
        if (nums == null || nums.length < 2) {
            return result;
        }

        var index1 = 0;
        var index2 = nums.length - 1;
        while (index1 < index2) {
            if (nums[index1] + nums[index2] < target) {
                index1++;
            } else if (nums[index1] + nums[index2] == target) {
                result[0] = index1 + 1;
                result[1] = index2 + 1;
                break;
            } else {
                index2--;
            }
        }

        return result;
    }
}

